import csv
for file in ['data/pickup_zones.csv','data/carriers.csv']:
 print('\n---',file)
 with open(file,newline='') as f:
  for r in csv.DictReader(f):
   if file.endswith('pickup_zones.csv') and r.get('zone')=='93': print(r)
   elif file.endswith('carriers.csv') and r.get('kind')=='trucker' and '93' in r.get('serves','').replace(' ','').split(','): print(r)
   elif file.endswith('carriers.csv') and r.get('kind')=='airline' and 'SGN' in r.get('serves','').split(','): print(r)
